from q import Stage, COMBO, COMBO2, COMBO3
from passages import SIJO1, SIJO2, SIJO3, SIJO4
import psg as P
T = P.T

S = Stage('a', 'STEP 2', '응용 — 작품·지문에 적용하기', '작품과 지문 속 시어·구절·문장에 개념을 적용하는 단계')
A, B, CC, D = '시조', '현대시', '논증', '문법'

S.grp(A, '[57~60] 다음 시조를 읽고 물음에 답하시오.', SIJO1)
S.mc(A, '초장의 진술 방식과 화자의 태도를 바르게 짝 지은 것은?', ['구체적 진술 - 임에 대한 원망', '일반적 진술 - 자신의 어리석음에 대한 자책', '일반적 진술 - 임을 떠나보낸 후회', '구체적 진술 - 임을 기다리는 설렘', '설의적 진술 - 이별의 체념'], 2,
     '초장 = 일반적 진술(자책), 중·종장 = 구체적 진술.', tag='학습지')
S.mc(A, '\'만중운산\'의 역할로 가장 적절한 것은?', ['시간적 배경을 제시해 애상감을 높인다.', '공간적 배경을 통해 그리움의 대상과 화자 사이의 정서적 거리감을 나타낸다.', '화자가 임을 만나러 가는 목적지를 보여 준다.', '임에 대한 원망을 직접 드러낸다.', '계절의 변화를 드러내 세월의 흐름을 보여 준다.'], 2,
     '만중운산 = 공간적 배경 → 임이 찾아오기 어려움(장애물, 거리감).', tag='빈출')
S.mc(A, '종장의 \'지는 잎 부는 바람\'에 대한 설명으로 가장 적절한 것은?', ['화자가 원망하는 대상이다.', '화자의 착각을 유발하는 자연물 소재이다.', '임이 보낸 편지를 상징한다.', '화자와 임을 이어 주는 매개체이다.', '임과의 이별을 알리는 소재이다.'], 2,
     '떨어지는 나뭇잎 소리·바람 소리를 임이 오는 소리로 착각 → 자연물을 소재로 화자의 감정을 드러냄.')
S.mc(A, '이 시조의 초장 → 중장 → 종장에 드러난 화자의 정서 흐름으로 알맞은 것은?', ['후회 → 미련 → 그리움', '자책 → 체념과 그리움 → 착각', '기대 → 허겁지겁 → 부끄러움', '변함없는 사랑 → 안타까움 → 간절함', '체념 → 원망 → 분노'], 2,
     '①은 (다), ③은 (라), ④는 (나)의 흐름.')

S.grp(A, '[61~63] 다음 시조를 읽고 물음에 답하시오.', SIJO2)
S.mc(A, '시간적 배경을 드러내는 시어를 바르게 묶은 것은?', ['신, 님', '월침삼경, 추풍', '님, 지는 닙', '온 뜻, 소리', '신, 월침삼경'], 2, '월침삼경(깊은 밤), 추풍(가을) → 시간적 배경으로 애상적 정서.', tag='학습지')
S.mc(A, '종장의 \'낸들 어이하리오\'에 쓰인 표현법은?', ['영탄법', '설의법', '대구법', '도치법', '반복법'], 2, '"나인들 어찌하겠는가" — 의문 형식이지만 답이 정해진 설의법.', tag='빈출')
S.bg(A, '이 시조에 쓰인 하강적 이미지를 <보기>에서 모두 고른 것은?', ['달이 짐(월침)', '잎이 짐(지는 닙)', '임을 속임'], 3, 'ㄷ은 이미지가 아닌 의문의 내용이다.')

S.grp(A, '[64~66] 다음 시조를 읽고 물음에 답하시오.', SIJO3)
S.sa(A, '영탄법이 쓰인 시어를 찾아 쓰시오.', '어져', '감탄사를 통해 이별의 슬픔과 후회를 효과적으로 드러냄.')
S.mc(A, '중장에 드러난 화자의 정서로 가장 알맞은 것은?', ['후회', '미련', '체념', '원망', '설렘'], 2, '초장 후회 / 중장 미련(붙잡을 수 있었으리라) / 종장 그리움.', tag='학습지')
S.mc(A, '초장 \'그릴 줄을 모로던가\'의 \'-던가\'에 대한 설명으로 가장 적절한 것은?', ['상대에게 질문하여 답을 요구한다.', '스스로에게 묻는 형식으로 후회를 강조한다.', '명령의 뜻으로 임을 붙잡는다.', '감탄의 뜻으로 기쁨을 드러낸다.', '미래의 일을 추측한다.'], 2, '의문형 어미 → 자신에게 묻는 형식 → 후회 강조.')

S.grp(A, '[67~71] 다음 시조를 읽고 물음에 답하시오.', SIJO4)
S.mc(A, '의태어가 <u>아닌</u> 것은?', ['곰븨님븨', '님븨곰븨', '천방지방', '지방천방', '위렁충창'], 5, '위렁충창 = 급히 달리는 발소리(의성어).', tag='빈출')
S.mc(A, '초장의 \'져녁밥을 일 지어 먹고\'에 담긴 화자의 마음으로 가장 알맞은 것은?', ['임에 대한 원망', '임을 기다리는 설렘과 서두름', '이별에 대한 체념', '자신의 행동에 대한 부끄러움', '가난한 생활에 대한 한탄'], 2, '임이 온다는 소식에 서두름 = 기대·설렘.')
S.mc(A, '\'중문 나서 대문 나가 지방 우희 치다라 안자\'의 전개 방식으로 알맞은 것은?', ['점층적 전개', '역순행적 구성', '수미상관', '대조적 구성', '선경후정'], 1, '중문 → 대문 → 문지방으로 점점 나아감(점층적 전개).', tag='필기')
S.mc(A, '화자가 임으로 착각한 대상을 가리키는 시어를 바르게 짝 지은 것은?', ['건넌 산 - 지방', '거머흿들 - 주추리 삼대', '보션 - 신', '정엣말 - 겻눈', '상년 - 칠월 사흔날'], 2, '거머흿들(거무희뜩한 것) = 주추리 삼대.')
S.mc(A, '종장에 드러난 화자의 태도로 가장 적절한 것은?', ['임을 원망하며 슬퍼한다.', '착각한 자신을 부끄러워하면서도 밤이라 다행이라 여긴다.', '다시는 임을 기다리지 않겠다고 다짐한다.', '남의 비웃음을 두려워해 숨는다.', '임이 오지 않은 것을 체념한다.'], 2, '"밤이라 다행" → 낙천적·해학적 태도.')

S.grp(B, '[] 다음 (가), (나)를 읽고 물음에 답하시오.',
      P.poem('(가)', T.YEONTAN, T.YEONTAN_AU, {'기꺼이 연탄 한 장 되는 것': '㉠', '방구들 선득선득해지는 날부터 이듬해 봄까지': '㉡', '힘쓰며 언덕길 오르는 거라네': '㉢',
                                             '매일 따스한 밥과 국물 퍼먹으면서도 몰랐네': '㉣', '한 덩이 재로 쓸쓸하게 남는 게 두려워': '㉤', '그 길을 만들 줄도 몰랐었네, 나는': '㉥'}, T.YEONTAN_NOTE)
      + P.poem('(나)', T.DAM, T.DAM_AU, {'저것은 벽': 'ⓐ', '담쟁이는 말없이 그 벽을 오른다.': 'ⓑ', '물 한 방울 없고, 씨앗 한 톨 살아남을 수 없는': 'ⓒ',
                                         '한 뼘이라도 꼭 여럿이 함께 손을 잡고 올라간다.': 'ⓓ', '푸르게 절망을 다 덮을 때까지': 'ⓔ', '담쟁이 잎 하나는 담쟁이 잎 수천 개를 이끌고': 'ⓕ'}))
S.mc(B, '(가)의 ㉠이 포함된 1연(삶이란 / 나 아닌 그 누구에게 / ㉠)에 쓰인 표현법은?', ['직유법', '은유법', '설의법', '대구법', '반어법'], 2, '\'삶이란 … 연탄 한 장 되는 것\' = \'A는 B이다\' 형식의 은유법.', tag='학습지')
S.mc(B, '(가)의 ㉡에서 \'선득선득해지는\'이 환기하는 감각적 이미지는?', ['시각적', '청각적', '촉각적', '후각적', '미각적'], 3, '서늘한 느낌 → 촉각.')
S.mc(B, '(가)의 \'부릉부릉\'에 대한 설명으로 적절한 것은?', ['의태어로, 연탄 차의 모양을 나타낸다.', '의성어로, 시에 생동감을 준다.', '색채어로, 선명한 이미지를 준다.', '촉각적 이미지를 드러낸다.', '화자의 슬픔을 직접 표현한다.'], 2, '음성 상징어(의성어) → 청각적 이미지, 생동감.')
S.mc(B, '(가)의 ㉢에서 \'언덕길\'의 의미로 가장 적절한 것은?', ['타인의 희생 덕분에 누리는 편안함', '이타적인 삶을 실천하는 데 따르는 고난과 힘겨움', '화자가 걸어온 이기적인 삶', '연탄이 만든 희생의 결과물', '추위에 떠는 이웃'], 2, '', tag='학습지')
S.mc(B, '(가)의 ㉣에서 \'따스한 밥과 국물\'의 의미로 가장 적절한 것은?', ['타인의 희생 덕분에 누리는 편안함', '연탄의 희생적 사랑', '화자의 이타적 행동', '추운 겨울의 시련', '가난한 이웃의 삶'], 1, '\'몰랐네\'부터 시선이 화자 자신에게로 옮겨 간다.')
S.mc(B, '(가)의 ㉤에서 \'한 덩이 재\'의 의미로 가장 적절한 것은?', ['이기적인 삶의 초라한 결과', '타인을 위해 온전히 희생하고 난 후의 모습', '화자가 두려워하지 않는 대상', '따뜻한 이웃의 마음', '연탄 차의 힘겨움'], 2, '화자는 이 모습이 \'두려워\' 희생하지 못했다.')
S.mc(B, '(가)의 ㉥에 쓰인 표현법과 효과를 바르게 짝 지은 것은?', ['설의법 - 깨달음 강조', '도치법 - 여운 형성, 부끄러움과 반성 강조', '반복법 - 운율 형성', '은유법 - 희생의 의미 형상화', '대구법 - 대비 강조'], 2, '정상 어순: "나는 그 길을 만들 줄도 몰랐었네."', tag='빈출')
S.mc(B, '(나)의 ⓐ에서 \'벽\'이 상징하는 바로 가장 적절한 것은?', ['희망과 생명력', '시련·고난·장애물', '함께하는 사람들', '앞장서 이끄는 사람', '안락한 휴식처'], 2, '')
S.mc(B, '(나)의 ⓑ에 드러난 담쟁이의 태도는?', ['체념', '극복 의지', '원망', '후회', '방관'], 2, '말없이 오른다 = 묵묵한 극복 의지.')
S.mc(B, '(나)의 ⓒ가 나타내는 것은?', ['담쟁이의 연대', '어떠한 희망도 없는 극한의 절망적 상황', '화자의 과거 회상', '계절의 변화', '담쟁이의 성장 과정'], 2, '필기: 극한의 상황.')
S.mc(B, '(나)의 ⓓ가 드러내는 모습은?', ['선구자적 모습', '연대를 통해 시련을 이겨 내는 모습', '홀로 고독하게 싸우는 모습', '벽 앞에서 좌절하는 모습', '과거를 반성하는 모습'], 2, '', tag='학습지')
S.mc(B, '(나)의 ⓔ에서 \'푸르게\'에 대한 설명으로 적절한 것은?', ['청각적 이미지로 절망을 드러낸다.', '색채어로 희망과 생명력을 드러낸다.', '의태어로 담쟁이의 움직임을 나타낸다.', '색채어로 절망과 좌절을 드러낸다.', '촉각적 이미지로 차가움을 드러낸다.'], 2, '색채어는 맞지만 의미는 희망·생명력.')
S.mc(B, '(나)의 ⓕ에서 \'담쟁이 잎 하나\'가 상징하는 바는?', ['민중', '선구자', '절망', '벽', '우리'], 2, '잎 하나 = 선구자, 잎 수천 개 = 함께하는 민중.', tag='학습지')
S.sa(B, '(나)에서 \'우리\'가 벽을 대하는 태도를 한 단어로 쓰시오.', '체념 (포기·좌절)', '담쟁이 = 극복 ↔ 우리 = 체념.')
S.sa(B, '(나)에서 담쟁이의 행동을 나타내는 서술어 네 개를 연의 순서대로 쓰시오.', '오른다 → 나아간다 → 올라간다 → 넘는다', '점층적 전개.')

S.grp(CC, '[] 다음 글을 읽고 물음에 답하시오.',
      P.prose('(가)', [T.W1, T.W2], {'하지만 과연 무엇이든지 빠르게 이루어지는 세상이 우리에게 좋기만 할까요?': '㉠', '모든 관찰에는 반드시 기다림의 시간이 필요합니다': '㉡', '꽃이 피기까지 지켜보는 일도 관찰에 해당합니다': '㉢'})
      + P.prose('(나)', [T.W3, T.W4, T.W5], {'스마트폰 카메라의 편리함과 기다림의 시간을 맞바꾼 것이지요': '㉣'}, figs={0: T.FIG_BRESSON()})
      + P.prose('(다)', [T.W6, T.W7, T.W8], figs={2: T.FIG_CEZANNE()})
      + P.prose('(라)', [T.W9, T.W10, T.W11], {'만약 폭포의 모습을 있는 그대로 그렸다면, 이러한 느낌을 낼 수 있었을까요?': '㉤'}, figs={0: T.FIG_JEONGSEON()})
      + P.prose('(마)', [T.W12, T.W13, T.W14], {'음식을 맛보는 일은 사는 일과 비슷해요': '㉥', '우연도 결국에는 포기하지 않고 끝까지 기다리는 사람에게 찾아오지요': '㉦'}, T.WAIT_AU))
S.mc(CC, '㉠의 기능으로 가장 적절한 것은?', ['빠른 세상에 대한 부정적 관점을 드러내며 문제를 제기한다.', '빠른 세상의 장점을 강조한다.', '예상 반론을 반박한다.', '글의 결론을 요약한다.', '구체적인 사례를 제시한다.'], 1, '필기: "본론 3명" — 뒤에 나올 세 사람(브레송·세잔·정선)을 암시.')
S.mc(CC, '㉡은 (가)의 연역 논증에서 무엇에 해당하는가?', ['대전제', '소전제', '결론', '사례', '반론'], 1, '대전제: 모든 관찰에는 기다림이 필요.')
S.mc(CC, '㉢은 (가)의 연역 논증에서 무엇에 해당하는가?', ['대전제', '소전제', '결론', '유추', '예상 반론'], 2, '결론: 꽃이 피기까지 지켜보는 일에도 반드시 기다림의 시간이 필요.')
S.mc(CC, '(나)~(라)에 제시된 인물과 설명을 잘못 연결한 것은?', ['브레송 - 프랑스의 사진작가', '세잔 - 프랑스의 화가', '정선 - 조선 후기의 화가', '브레송 - 「생 라자르 역 뒤에서」', '세잔 - 「박연 폭포」'], 5, '「박연 폭포」는 정선. 세잔은 「생트 빅투아르산」 연작.')
S.mc(CC, '(나)에서 브레송이 사진을 찍을 때 인위적으로 장면을 연출하는 것에 반대한 까닭은?', ['사진기의 성능이 좋지 않았기 때문에', '작가가 원하는 결정적인 순간을 포착하는 것이 가장 중요하다고 생각했기 때문에', '연출하는 데 비용이 많이 들었기 때문에', '많은 사진을 빠르게 찍고 싶었기 때문에', '사람들이 연출된 사진을 싫어했기 때문에'], 2, '교과서 날개 질문.', tag='교과서')
S.mc(CC, '㉣의 의미로 가장 적절한 것은?', ['스마트폰 덕분에 기다림의 시간이 더 길어졌다.', '쉽게 찍고 지울 수 있는 편리함을 얻는 대신 기다림의 시간을 잃었다.', '스마트폰 사진에는 기다림의 흔적이 가득하다.', '스마트폰은 결정적 순간을 포착하기에 가장 좋은 기계이다.', '브레송도 스마트폰을 사용했을 것이다.'], 2, '찍기 쉬운 만큼 지우기도 쉬워 빠르게 연달아 찍음.')
S.mc(CC, '(다)에서 세잔이 20년 동안 그린 주제로, 매일 아침 언덕에 올라 관찰한 대상은?', ['박연 폭포', '생트 빅투아르산', '생 라자르 역', '프로방스의 바다', '커다란 소나무 숲'], 2, '1901년부터 프로방스 지방에서 산의 모든 변화를 지켜봄.')
S.mc(CC, '(라)에서 정선의 「박연 폭포」에 대한 설명으로 옳은 것은?', ['폭포를 실제보다 작게 그렸다.', '정자와 갓 쓴 선비를 실제보다 크게 그렸다.', '폭포와 주변 요소는 과장되게 크고 길게, 정자와 선비는 작게 그렸다.', '대상을 있는 그대로 사실적으로 그렸다.', '짧은 시간에 한 번 보고 그렸다.'], 3, '폭포의 웅장함과 역동성을 드러내려 과감히 변형.', tag='빈출')
S.mc(CC, '㉤에 대한 설명으로 가장 적절한 것은?', ['독자에게 모르는 정보를 묻는다.', '대상을 변형했기 때문에 웅장함과 생생함을 느낄 수 있다는 점을 의문 형식으로 강조한다.', '정선의 그림이 사실적이라고 주장한다.', '예상 반론을 제시한다.', '글 전체의 결론을 요약한다.'], 2, '있는 그대로 그렸다면 그런 느낌을 낼 수 없었다 → 변형의 효과 강조.')
S.sa(CC, '(라)에서 글쓴이가 말한 \'느낌을 전달하는 능력\'이 무엇인지 쓰시오.', '익숙한 것에서 낯선 차이를 포착해 내는 것', '세상 만물은 모두 저마다의 차이를 가지고 있음.')
S.mc(CC, '㉥이 포함된 (마)의 둘째 문단에 쓰인 논증 방법과 비교 대상을 바르게 짝 지은 것은?', ['연역 - 관찰과 꽃', '귀납 - 브레송, 세잔, 정선', '유추 - 음식을 맛보는 일과 사는 일', '유추 - 사진과 그림', '귀납 - 음식과 풍경'], 3, '두 대상의 유사성(사람마다 다름, 천천히 음미해야 함)을 근거로 추리.')
S.mc(CC, '㉦은 어떤 예상 반론에 대한 반박인가?', ['기다림은 지루하다.', '누군가는 기다림 없이 원하는 순간을 우연히 얻었다.', '빠른 세상이 더 편리하다.', '좋은 기계가 있어야 좋은 사진을 찍는다.', '관찰은 누구나 쉽게 할 수 있다.'], 2, '')
S.grp(CC, '')
S.mc(CC, '다음 글에 나타난 오류는?', ['성급한 일반화의 오류', '결합의 오류', '인과 관계의 오류', '논점 일탈의 오류', '피장파장의 오류'], 1, '두 명의 사례로 전체를 판단.', box='내가 만난 ○○ 가게 직원 두 명이 불친절했어. 그 가게 직원들은 모두 불친절해.')
S.mc(CC, '다음 글에 나타난 오류는?', ['흑백 사고의 오류', '미끄러운 비탈길의 오류', '허수아비 공격의 오류', '인신공격의 오류', '감정에 호소하는 오류'], 2, '근거 없는 연쇄 → 극단적 결과.', box='오늘 게임을 한 시간 하면 내일은 두 시간 하게 되고, 결국 공부를 포기해 인생을 망치게 될 거야.')

S.mc(D, '"민수가 동생에게 책을 주었다."의 문장 성분을 차례대로 바르게 나열한 것은?', ['주어 - 목적어 - 부사어 - 서술어', '주어 - 부사어 - 목적어 - 서술어', '주어 - 보어 - 목적어 - 서술어', '주어 - 관형어 - 목적어 - 서술어', '주어 - 부사어 - 보어 - 서술어'], 2, '동생에게 = 체언 + 부사격 조사 → 부사어(필수적 부사어).')
S.mc(D, '보어가 쓰인 문장은?', ['물이 얼음으로 되었다.', '그는 의사가 되었다.', '꽃이 활짝 피었다.', '나는 학교에 갔다.', '하늘이 푸르다.'], 2, '\'되다\' 앞 + 보격 조사 \'가\'. ①은 \'으로\' → 부사어.', tag='빈출')
S.mc(D, '밑줄 친 부분이 관형어인 것은?', ['<u>빨리</u> 달렸다.', '<u>새</u> 옷을 입었다.', '<u>학교에서</u> 만났다.', '<u>아주</u> 빠르다.', '<u>와</u>, 눈이다!'], 2, '관형사 \'새\' → 관형어.')
S.mc(D, '밑줄 친 부사어의 형식이 \'체언 + 부사격 조사\'인 것은?', ['비행기가 <u>매우</u> 빠르다.', '책을 <u>가방에</u> 넣었다.', '강아지가 <u>귀엽게</u> 생겼다.', '<u>설마</u> 그가 그랬겠니?', '자동차가 <u>빠르게</u> 달린다.'], 2, '①④ 부사, ③⑤ 용언 어간 + -게.')
S.mc(D, '독립어가 쓰인 문장이 <u>아닌</u> 것은?', ['야호! 방학이다.', '은우야, 창문 좀 열어라.', '사랑, 가장 소중한 선물이다.', '네, 알겠습니다.', '그러나 그것은 사실이었다.'], 5, '\'그러나\'는 접속 부사 → 부사어.')
S.mc(D, '\'무엇이 어떠하다\'의 구조를 지닌 문장은?', ['동생은 일곱 살이다.', '석진이가 달린다.', '하늘이 푸르다.', '그는 가수가 되었다.', '이것은 책상이다.'], 3, '형용사 서술어 = 어떠하다.', tag='학습지')
S.mc(D, '밑줄 친 목적어의 형식이 \'체언 + 보조사 + 목적격 조사\'인 것은?', ['나는 <u>너를</u> 좋아해.', '나는 <u>너</u> 좋아해.', '나는 <u>너만</u> 좋아해.', '나는 <u>너만을</u> 좋아해.', '<u>너도</u> 왔구나.'], 4, '')
S.mc(D, '홑문장인 것은?', ['비가 오고 바람이 분다.', '동생이 방긋 웃었다.', '내가 신호를 보내면 나가라.', '비가 오는 소리가 들린다.', '그는 키가 크다.'], 2, '⑤는 서술절을 가진 안은문장.', tag='학습지')
S.mc(D, '대등하게 이어진문장은?', ['바람이 불어서 모자가 날아갔다.', '하늘은 맑으며 바람은 상쾌하다.', '밥을 먹어도 배가 고프다.', '책을 사러 서점에 갔다.', '봄이 오면 꽃이 핀다.'], 2, '-(으)며 나열. 나머지는 종속.', tag='학습지')
S.mc(D, '종속적으로 이어진문장의 연결 어미와 의미 관계를 잘못 연결한 것은?', ['-아서/-어서 : 원인', '-(으)면 : 조건', '-(으)려고 : 의도', '-는데 : 배경(상황)', '-아도/-어도 : 시간'], 5, '-아도/-어도 = 양보.')
S.mc(D, '[　] 안이 명사절인 것은?', ['[아기가 우는] 소리가 들린다.', '농부는 [농사가 잘되기]를 바란다.', '민후는 [땀이 나도록] 뛰었다.', '토끼는 [앞발이 짧다].', '그는 [시험에 붙었다고] 말했다.'], 2, '명사형 어미 -기.', tag='학습지')
S.mc(D, '[　] 안이 관형절인 것은?', ['[내가 어제 본] 영화가 재미있었다.', '[지수가 해냈음]이 분명하다.', '드라마가 [눈물이 나게] 슬프다.', '승재는 [마음씨가 곱다].', '진수가 [예고도 없이] 돌아왔다.'], 1, '관형사형 어미 -ㄴ.')
S.mc(D, '서술절을 가진 안은문장은?', ['그는 선생님이 아니다.', '그는 고등학생이 되었다.', '코끼리는 코가 길다.', '그는 정말 착하다.', '물이 얼음이 되었다.'], 3, '주어 + [주어 + 서술어] 구조.', tag='빈출')
S.sa(D, '다음 직접 인용 문장을 간접 인용 문장으로 바꾸시오.', '그는 시험을 통과했다고 말했다.', '큰따옴표를 없애고 조사 \'라고\' → \'고\'.', box='그는 "시험을 통과했어."라고 말했다.', tag='필기')
